// Change loop intent without restarting the AudioContext clock or the current beat.
function replaceFutureGate(at){
 const old=gate;if(old){const fade=Math.max(ctx.currentTime,at-.003);old.gain.cancelScheduledValues(fade);old.gain.setValueAtTime(1,fade);old.gain.linearRampToValueAtTime(0,at);setTimeout(()=>old.disconnect(),Math.max(0,(at-ctx.currentTime)*1000)+100);}
 makeGate();gate.gain.setValueAtTime(0,ctx.currentTime);gate.gain.setValueAtTime(0,at);gate.gain.linearRampToValueAtTime(1,at+.003);
 if(midiOut){try{midiOut.clear();const stamp=performance.now()+Math.max(0,at-ctx.currentTime)*1000;midiOut.send([0xb0,123,0],stamp);for(const ev of transport.queue){if(ev.end||ev.count!==undefined||ev.time<=ctx.currentTime||ev.time>=at)continue;const pat=strumStep(song,ev.tick);if(pat.type==='D'||pat.type==='U')strum(chordAt(ev.tick),ev.time,pat.velocity,pat.type==='U');else if(pat.type==='X')chuck(ev.time,pat.velocity);}}catch{}}
}
function setPlaybackMode(mode){
 if(!['once','twice','loop'].includes(mode))return;
 const old=playbackPlan(),playing=transport.state==='playing',d=duration();let phase=playing?(ctx.currentTime-transport.origin)/d:transport.pos/d;
 const beforeCount=phase<(transport.countUntil||0),oldTick=mappedTick(phase,old),oldRound=phase<old.repeatEnd?Math.max(0,Math.floor((phase-old.start)/old.length)):Math.max(0,old.passes-1);
 checkpoint();song.loop=mode==='loop';if(mode!=='loop')song.playCount=mode==='twice'?2:1;
 if(activeRange){activeRange.loop=song.loop;activeRange.playCount=song.playCount;}$('rangeLoop').checked=song.loop;
 const p=playbackPlan(),wasEnding=!beforeCount&&phase>=old.repeatEnd,restartPass=wasEnding&&mode!=='once';
 let nextPhase=beforeCount?phase:restartPass?p.start+(mode==='twice'?p.length:0):oldTick+(mode==='twice'&&(oldRound>=1||wasEnding)?p.length:0);
 const shift=phase-nextPhase;
 if(shift){transport.origin+=shift*d;transport.next-=shift;transport.pos-=shift*d;for(const ev of transport.queue)if(ev.absolute!==undefined)ev.absolute-=shift;lastVisual=-999;}
 phase=nextPhase;
 if(!beforeCount)transport.countUntil=p.start;
 if(playing){
  clearTimeout(transport.timer);transport.endQueued=false;
  if(restartPass){const at=ctx.currentTime+.015;replaceFutureGate(at);transport.queue=[];transport.origin=at-phase*d;transport.next=Math.floor(phase);lastVisual=-999;}
  else{
   const index=transport.queue.findIndex(ev=>ev.end?(p.loop||Math.abs((ev.time-transport.origin)/d-p.finish)>.001):ev.count===undefined&&((!p.loop&&ev.absolute>=p.finish)||ev.tick!==mappedTick(ev.absolute,p)));
   if(index>=0){const ev=transport.queue[index];transport.next=ev.absolute??Math.round((ev.time-transport.origin)/d);if(!ev.end)replaceFutureGate(Math.max(ctx.currentTime+.001,ev.time));transport.queue=transport.queue.slice(0,index);}
  }
  schedule();
 }else transport.pos=phase*d;
 $('loopToggle').value=mode;$('stageLoop').value=mode;
 if(!beforeCount){transport.tick=Math.floor(mappedTick(phase,p));renderPosition(transport.tick,phase);}
 changed();updateTransport();
}
function setLoop(enabled){setPlaybackMode(enabled?'loop':'once');}
// Measure progress in elapsed audio time, including offbeat swing and repeated passages.
function chordCueWindow(phase,counting=false){
 const p=playbackPlan(),until=transport.countUntil||0;
 if(counting){const start=until-countInSteps();return {start,end:until,progress:clamp((phase-start)/(until-start),0,1),chord:chordAt(Math.floor(mappedTick(until,p))),counting:true};}
 if(!p.loop&&phase>=p.finish)return null;
 const grid=Math.max(p.start,Math.floor(swingPhase(phase)+1e-8)),current=chordAt(Math.floor(mappedTick(grid,p))),limit=p.length+config().steps;
 const timeAt=at=>at+(song.meter!=='6/8'&&at%2?song.swing:0);
 let first=grid,next=null;
 for(let d=1;d<=limit&&grid-d>=p.start;d++){if(chordAt(Math.floor(mappedTick(grid-d,p)))!==current)break;first=grid-d;}
 for(let d=1;d<=limit;d++){const at=grid+d;if(!p.loop&&at>=p.finish)break;const chord=chordAt(Math.floor(mappedTick(at,p)));if(chord!==current){next={at,chord};break;}}
 if(!next)return null;const start=timeAt(first),end=timeAt(next.at);
 return {start,end,progress:clamp((phase-start)/(end-start),0,1),chord:next.chord,current};
}
function updateChordProgress(phase,counting=false){
 const cue=transport.state==='finished'?null:chordCueWindow(phase,counting);
 for(const prefix of ['next','practice']){const bar=$(prefix+'Progress'),fill=$(prefix+'ProgressFill');if(!bar||!fill)continue;bar.hidden=!cue;if(!cue)continue;
  fill.style.transform='scaleX('+cue.progress+')';const percent=Math.round(cue.progress*100);if(bar.getAttribute('aria-valuenow')!==String(percent))bar.setAttribute('aria-valuenow',String(percent));
  const label=cue.counting?'Starting the song':cue.chord==='--'?'Preparing to rest':'Preparing for '+cue.chord;if(bar.getAttribute('aria-label')!==label)bar.setAttribute('aria-label',label);
 }
 if(cue&&!counting){$('nextLabel').textContent='Up next';$('nextChord').textContent=cue.chord==='--'?'Rest':cue.chord;$('nextCount').textContent='Get your fingers ready';}
}
nextChange=function(tick,phase=displayPhase(tick)){
 const current=chordAt(tick),p=playbackPlan();for(let offset=1;offset<=p.length+config().steps;offset++){const abs=phase+offset;if(!p.loop&&abs>=p.finish)return null;const t=Math.floor(mappedTick(abs,p));if(chordAt(t)!==current)return {chord:chordAt(t),offset};}return null;
};
start=async function(from=null){if(isProjector)return;if(transport.state==='playing'){pause();return;}const gen=++transport.generation;try{await initAudio();}catch(e){toast(e.message||'Tap Play again to enable sound.');return;}if(gen!==transport.generation)return;if(soundState!=='ready'&&!midiOut)for(const note of new Set(song.measures.flatMap(m=>m.chords.flatMap(c=>(CHORD_FINGERINGS[c.chord]||[]).map((f,i)=>[67,60,64,69][i]+f)))))stringBuffer(note);
 clearTimers();silence();makeGate();const d=duration();if(from!==null&&activeRange&&(from<activeRange.start||from>=activeRange.end))activeRange=null;const w=windowBounds();const resume=transport.state==='paused'&&from===null;if(!resume){let target=from===null?w.start:Math.floor(clamp(from,0,song.measures.length-1))*config().steps;if(w.loop&&target>=w.end)target=w.start;transport.countUntil=target;const p=playbackPlan(),phase=target>=p.bodyEnd&&!p.loop?target+(p.passes-1)*p.length:target;transport.countUntil=phase;transport.pos=(phase-($('countIn').checked?countInSteps():0))*d;transport.tick=target;}transport.origin=ctx.currentTime+.08-transport.pos;transport.next=Math.floor(transport.pos/d+1e-6);transport.endQueued=false;transport.state='playing';lastVisual=-999;schedule();draw();updateTransport();};
schedule=function(){if(transport.state!=='playing'||transport.endQueued)return;const d=duration(),n=config().steps,w=playbackPlan();let limit=0;while(transport.origin+transport.next*d<ctx.currentTime+.12&&limit++<128){const abs=transport.next++;if(abs>=w.finish&&!w.loop){transport.queue.push({time:transport.origin+w.finish*d,end:true});transport.endQueued=true;break;}const counting=abs<transport.countUntil,tick=counting?transport.tick:mappedTick(abs,w),step=tick%n,sw=!counting&&song.meter!=='6/8'&&step%2?song.swing*d:0,time=transport.origin+abs*d+sw;if(time<ctx.currentTime-.012)continue;
 if(counting){const elapsed=abs-transport.countUntil+countInSteps();if(elapsed%countStepSize()===0)click(time,countInAccent(elapsed));transport.queue.push({time,absolute:abs,count:abs-transport.countUntil});}
 else{scheduleSongStep(tick,time,abs);transport.queue.push({time,absolute:abs,tick});}}
 if(!transport.endQueued&&transport.state==='playing')transport.timer=setTimeout(schedule,25);};
draw=function(){if(transport.state!=='playing')return;const now=ctx.currentTime;while(transport.queue.length&&transport.queue[0].time<=now){const ev=transport.queue.shift();if(ev.end){finish();return;}if(ev.absolute!==lastVisual){lastVisual=ev.absolute;if(ev.count!==undefined)renderCount(ev.count);else{transport.tick=ev.tick;renderPosition(ev.tick,ev.absolute);}broadcastProjection();}}
 const abs=(now-transport.origin)/duration();renderLyricsAt(abs,abs<transport.countUntil);transport.frame=requestAnimationFrame(draw);};
const originalStop=stop;
stop=function(redraw=true){resetLyricScroll();originalStop(false);transport.countUntil=windowBounds().start;transport.tick=windowBounds().start;transport.pos=transport.tick*duration();$('endingCue').textContent='';if(redraw){renderPosition(transport.tick);updateTransport();}broadcastProjection();};
const originalPause=pause;
pause=function(){originalPause();broadcastProjection();};
finish=function(){clearTimers();const w=playbackPlan();transport.state='finished';transport.pos=w.finish*duration();transport.tick=w.scoreEnd-1;transport.generation++;silence();$('stage').classList.remove('counting');renderLyricLines('','','finished',false);$('lyricFill').style.width='100%';$('nextChord').textContent='✓';$('nextCount').textContent=activeRange?'Passage complete':'Song complete';$('endingCue').textContent='';updateTransport();updatePracticeDisplay(transport.tick,false,true);broadcastProjection();};
seek=function(bar){
 const target=Math.floor(clamp(bar,0,song.measures.length-1)),playing=transport.state==='playing',old=playbackPlan(),oldPhase=displayPhase(transport.tick),round=old.passes===2&&!old.loop&&oldPhase>=old.start+old.length?1:0;
 if(activeRange&&(target<activeRange.start||target>=activeRange.end))activeRange=null;
 stop(false);const p=playbackPlan(),tick=target*config().steps,phase=tick+(p.passes===2&&!p.loop&&(round||tick>=p.bodyEnd)?p.length:0);
 transport.pos=phase*duration();transport.tick=tick;transport.countUntil=p.start;transport.state='paused';renderPosition(tick,phase);if(playing)start();else updateTransport();
};
const originalCount=renderCount;
renderCount=function(abs){originalCount(abs);const tick=transport.countUntil||0,c=chordAt(tick);$('currentChord').textContent=c==='--'?'Rest':c;$('stageDiagram').innerHTML=diagram(c);$('nextChord').textContent=c==='--'?'Rest':c;$('endingCue').textContent=song.meter==='6/8'?compoundCountWords().join(' · '):'Ready, steady…';fitLyricText();updatePracticeDisplay(tick,true,false,Math.floor((abs+countInSteps())/countStepSize())+1);};
const originalPosition=renderPosition;
renderPosition=function(tick,phase=displayPhase(tick)){
 originalPosition(tick,phase);const p=playbackPlan(),again=repeatsAfter(phase,p),n=config().steps;let cue='';
 if(isEndingMeasure(song,tick))cue=tick%n===0?'Last strum!':'';
 else if(tick>=p.bodyEnd-n)cue=again?'Back to the beginning':p.scoreEnd>p.bodyEnd?'Next measure · one final strum':'';
 $('endingCue').textContent=cue;
 if(transport.state==='playing'&&p.passes===2&&!p.loop){const pass=phase>=p.start+p.length?2:1,status=isEndingMeasure(song,tick)?'Final chord':`Pass ${pass} of 2 · Measure ${Math.floor(tick/n)+1}`;$('editorStatus').textContent=status;$('stageStatus').textContent=status;}
 if(!nextChange(tick,phase))$('nextCount').textContent=again?'Keep going through the repeat':'Through the end';
 updatePracticeDisplay(tick);
};
const originalAll=renderAll;
renderAll=function(){song.band=song.band||{...DEFAULT_BAND};song.theme=song.theme||'sunny';originalAll();applyTheme();$('volume').value=song.band.ukulele;renderSectionChips();$('rangeStart').max=song.measures.length;$('rangeEnd').max=song.measures.length;$('rangeEnd').value=Math.min(song.measures.length,+$('rangeEnd').value||4);if(activeRange&&activeRange.end>song.measures.length)activeRange=null;};
const originalMeasures=renderMeasures;
renderMeasures=function(){originalMeasures();document.querySelectorAll('#measuresGrid [data-measure]').forEach((node,i)=>{const name=song.measures[i].sectionStart;if(name)node.insertAdjacentHTML('afterbegin',`<span class="section-marker">${esc(name)}</span>`);node.classList.toggle('in-range',!!activeRange&&i>=activeRange.start&&i<activeRange.end);});};
const originalTransport=updateTransport;
updateTransport=function(){originalTransport();if(transport.state==='finished')updateChordProgress(transport.pos/duration());if($('exercisePlay'))$('exercisePlay').textContent=transport.state==='playing'?'Ⅱ Pause':transport.state==='paused'?'▶ Resume':'▶ Start practice';broadcastProjection();};
function renderSectionChips(){$('sectionChips').innerHTML=sections().map((s,i)=>`<button data-section="${i}" title="Select ${esc(s.name)}">${esc(s.name)} <small>${s.start+1}–${s.end}</small></button>`).join('');$('rangeStatus').textContent=activeRange?`Practicing measures ${activeRange.start+1}–${activeRange.end}${activeRange.loop?' · repeats until stopped':''}`:'Choose a few measures to practice together.';}
function scheduleSongStep(tick,time,phase=tick){
 const step=tick%config().steps,pat=strumStep(song,tick),chord=chordAt(tick);
 scheduleBand(tick,time,phase);
 if(pat.type==='D'||pat.type==='U')strum(chord,time,pat.velocity,pat.type==='U');else if(pat.type==='X'&&chord!=='--')chuck(time,pat.velocity);
 if(!isEndingMeasure(song,tick)&&$('metronomeToggle').checked&&step%config().beat===0)click(time,step===0);
}
function scheduleBand(tick,time,phase=tick){
 const ending=isEndingMeasure(song,tick);
 if(tick%config().steps===0&&bandBus){
  if(ending){
   for(const voice of sampleVoices)if(voice.instrument!=='uke')voice.release(time,.02);
   for(const key of ['drums','shaker','melody']){const gain=bandBuses[key].gain;gain.setValueAtTime(song.band[key]/100,time);gain.linearRampToValueAtTime(0,time+.02);}
  }else if(tick===0||isEndingMeasure(song,tick-1)){
   bandBus.gain.setValueAtTime(song.band.enabled?1:0,time);for(const key of ['bass','drums','shaker','melody'])bandBuses[key].gain.setValueAtTime(song.band[key]/100,time);
  }
 }
 dampChangedChord(chordAt(tick),time);for(const event of bandEvents(song,tick,{start:windowBounds().start,end:playbackPlan().scoreEnd,loop:repeatsAfter(phase)}))playBandEvent(event,time);
}
function tone(note,time,length,volume,type){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=440*2**((note-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+.012);g.gain.exponentialRampToValueAtTime(.001,time+length);o.connect(g);g.connect(gate);o.start(time);o.stop(time+length+.02);o.onended=()=>{o.disconnect();g.disconnect();};}
function noiseHit(time,length,volume,hz){const b=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*length),ctx.sampleRate),data=b.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/data.length*6);const s=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();s.buffer=b;f.type='highpass';f.frequency.value=hz;g.gain.value=volume;s.connect(f);f.connect(g);g.connect(gate);s.start(time);s.onended=()=>{s.disconnect();f.disconnect();g.disconnect();};}
function swingPhase(tick){if(song.meter==='6/8'||!song.swing)return tick;const pair=Math.floor(tick/2)*2,split=pair+1+song.swing;return tick<split?pair+(tick-pair)/(1+song.swing):pair+1+(tick-split)/(1-song.swing);}
function showClass(tool,title,eyebrow='Make music together'){if(classTool!==tool)leaveExercise();classTool=tool;$('classTitle').textContent=title;$('classEyebrow').textContent=eyebrow;if(!$('classModal').open)$('classModal').showModal();}
function closeClass(){leaveExercise();$('classModal').close();classTool='';lessonActive=false;$('lessonDock').hidden=true;}
function enterExercise(raw){if(!exerciseBackup){clearTimeout(autosaveTimer);exerciseBackup={song:clone(song),selected,dirty,undo:clone(undoStack),range:activeRange,countIn:$('countIn').checked};}stop(false);activeRange=null;song=normalizeSong(raw);selected=0;$('countIn').checked=true;renderAll();}
function leaveExercise(){if(!exerciseBackup)return;stop(false);const b=exerciseBackup;exerciseBackup=null;song=b.song;selected=b.selected;dirty=b.dirty;undoStack=b.undo;activeRange=b.range;$('countIn').checked=b.countIn;renderAll();if(dirty)changed();}
function openLesson(step=0){if(transport.state==='playing')pause();leaveExercise();if(step===0)challengeStars=0;lessonActive=true;lessonStep=step;showClass('lesson','Teach this song','A little rehearsal, then the whole band');renderLesson();}
function lessonNavigation(){return `<div class="lesson-nav"><button data-lesson="${Math.max(0,lessonStep-1)}"${lessonStep===0?' disabled':''}>← Back</button><button data-repeat>↻ Repeat this step</button><button data-lesson="${Math.min(3,lessonStep+1)}" class="primary">${lessonStep===3?'Ready to perform':'Next step →'}</button></div>`;}
function renderLesson(){leaveExercise();const source=clone(song),names=songChords(),pair=suggestPair();let html=`<div class="lesson-steps">${['1 · Find the chords','2 · Change together','3 · Feel the strum','4 · Play the song'].map((x,i)=>`<button data-lesson="${i}" class="${i===lessonStep?'active':''}" aria-current="${i===lessonStep?'step':'false'}">${x}</button>`).join('')}</div>`;
 if(lessonStep===0){html+=`<h3 class="lesson-head">Fingers ready?</h3><p class="lesson-note">Explore the chords in “${esc(song.title)}.” Make each shape, strum once, and listen together. Open circles mean open strings.</p><div class="lesson-chords">${names.map(c=>`<button class="lesson-chord" data-hear="${esc(c)}" aria-label="Hear ${esc(c)} chord"><strong>${esc(c)}</strong>${diagram(c)}<small>♪ Hear this chord</small></button>`).join('')||'<p>This song contains rests. Add a chord to begin.</p>'}</div><p class="hint">${names.includes('C')?'C: ring finger on string 1 (A), third fret. ':''}G–C–E–A · Soprano and concert ukulele</p>`;}
 if(lessonStep===1){html+=`<h3 class="lesson-head">Make a smooth change</h3><p class="lesson-note">${names.length>1?'Practice a chord change from this song. Give everyone time to find the next shape.':'A one-chord song! Practice lifting your fingers, then finding the shape again.'}</p>`+challengeForm(pair[0],pair[1],true);}
 if(lessonStep===2){html+=`<h3 class="lesson-head">Feel the strum</h3><p class="lesson-note">Hold ${esc(names[0]||'C')} and practice <b>${esc(STRUM_PATTERNS[song.pattern].name)}</b>. Keep your hand moving on the quiet strokes. Say “down” and “up” together before adding your voices.</p>${practiceScreen()}<div class="strum-steps">${patternHTML()}</div><div class="row" style="margin-top:16px"><button id="exercisePlay" class="primary">▶ Start practice</button><button data-exercise-stop>■ Stop</button><label>Practice tempo<input id="strumPracticeTempo" type="number" min="40" max="200" value="${Math.max(40,source.tempo-12)}"></label></div>`;}
 if(lessonStep===3){html+=`<h3 class="lesson-head">Your class is the band</h3><p class="lesson-note">You know the shapes, the changes, and the strum. Bring them together! Your ${countInCounts()}-${song.meter==='6/8'?'big-beat':'beat'} intro gives everyone time to get ready.</p><div class="empty-card"><b>${esc(song.title)}</b><p>${esc(THEMES[song.theme])} · ${song.tempo} BPM · ${songChords().join(' · ')||'Rest'}</p><p>Watch the next chord, sing the words, and finish on the cutoff cue.</p></div><div class="row" style="margin-top:18px"><button data-lesson-perform class="new-song-cta">Open the stage →</button><button data-lesson-band>♫ Choose our band</button></div>`;}
 $('classContent').innerHTML=html+lessonNavigation();if(lessonStep===1)buildChallenge(false);if(lessonStep===2){const ex=clone(source);ex.id=null;ex.title='Feel the strum · '+source.title;ex.tempo=Math.max(40,source.tempo-12);ex.loop=true;ex.band.enabled=false;ex.measures=Array.from({length:4},()=>measure(names[0]||'C','Listen. Strum. Keep your hand moving.'));enterExercise(ex);updatePracticeDisplay(0);}}
function suggestPair(){const events=song.measures.flatMap(m=>m.chords.map(c=>c.chord)).filter(c=>c!=='--'),counts=new Map();for(let i=1;i<events.length;i++)if(events[i]!==events[i-1]){const key=events[i-1]+'|'+events[i];counts.set(key,(counts.get(key)||0)+1);}const best=[...counts].sort((a,b)=>b[1]-a[1])[0];return best?best[0].split('|'):[events[0]||'C',events[0]||'G7'];}
function practiceScreen(){return `<div class="practice-display"><div class="practice-current"><small id="practiceLabel">PLAY THIS CHORD</small><strong id="practiceChord">C</strong></div><div class="practice-diagram" id="practiceDiagram"></div><div class="practice-next"><span id="practiceMessage">Find your starting shape</span><b id="practiceNext">G7</b><div class="chord-cue"><div class="chord-change-progress" id="practiceProgress" role="progressbar" aria-label="Progress to the next chord" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" hidden><i id="practiceProgressFill"></i></div><span id="practiceCountdown">Ready when you are</span></div></div></div>`;}
function challengeForm(a,b,lesson=false){const options=c=>chordOptions(c).replace(/<option value="--"[^>]*>Rest<\/option>/,'');return `<div class="practice-controls"><label>First chord<select id="challengeA">${options(a)}</select></label><label>Next chord<select id="challengeB">${options(b)}</select></label><label>Beats per chord<select id="challengeBeats"><option value="8">8 · extra time</option><option value="4" selected>4 · steady start</option><option value="2">2 · ready for more</option></select></label><label>Tempo<input id="challengeTempo" type="number" min="40" max="140" value="${Math.min(72,song.tempo)}"></label></div>${practiceScreen()}<div class="row"><button id="exercisePlay" class="primary">▶ Start practice</button><button data-exercise-stop>■ Stop</button><button data-earned class="new-song-cta">We’ve got it! ✦</button><button data-next-level>Try fewer beats</button></div><div class="shell-progress" aria-label="Class progress: ${challengeStars} of 3 stars">${[1,2,3].map(n=>`<span class="${n<=challengeStars?'earned':''}" aria-hidden="true">★</span>`).join('')}</div><p class="team-message" id="teamMessage">${challengeStars>=3?'Three class stars! Celebrate, or try fewer beats.':'Listen together. Your teacher awards each class star.'}</p><p class="hint">${lesson?'This practice uses a simple down strum. Your song keeps its original strumming pattern.':'This is a whole-class challenge. Stars come from the teacher’s “We’ve got it!” button.'}</p>`;}
function openChallenge(){leaveExercise();lessonActive=false;challengeStars=0;const pair=suggestPair();showClass('challenge','The chord-change challenge','Ready, steady, switch!');$('classContent').innerHTML=`<p class="lesson-note">Choose two shapes, set a comfortable pace, and earn three stars together. Everyone gets the full preparation time.</p>${challengeForm(...pair)}`;buildChallenge(false);}
function buildChallenge(play=false){const a=$('challengeA').value,b=$('challengeB').value,beats=+ $('challengeBeats').value||4,bpm=Math.round(clamp($('challengeTempo').value,40,140,64));$('challengeTempo').value=bpm;const source=exerciseBackup?.song||song,meter=beats===2?'2/4':'4/4',copies=beats===8?2:1;const ex=template('Chord challenge · '+a+' to '+b,meter,bpm,METERS[meter].default,Array.from({length:4},(_,i)=>Array(copies).fill(i%2?b:a)).flat(),[],'Whole-class chord practice','');ex.theme=source.theme;ex.band={...source.band,enabled:false};ex.loop=true;ex.measures.forEach((m,i)=>{if(i%copies===0){m.lyric=`Play ${m.chords[0].chord} · prepare ${m.chords[0].chord===a?b:a}`;m.lyricSpan=copies;}});enterExercise(ex);updatePracticeDisplay(0);if(play)start();}
function updatePracticeDisplay(tick,counting=false,finished=false,count=1){if(!$('practiceChord'))return;const c=chordAt(tick),next=nextChange(tick);$('practiceChord').textContent=c==='--'?'Rest':c;$('practiceLabel').textContent=counting?'GET READY':'PLAY THIS CHORD';$('practiceNext').textContent=counting?(song.meter==='6/8'?countInPrompt(count):String(count)):next?.chord||c;$('practiceMessage').textContent=finished?'':counting?'Count in':classTool==='lesson'&&lessonStep===2?'Keep your hand moving':'Get ready for';$('practiceCountdown').textContent=finished?'Ready for another round?':counting?`Start after ${countInCounts()}`:next?'Get your fingers ready':'Hold this shape';const shape=$('practiceDiagram');if(shape&&shape.dataset.chord!==c){shape.innerHTML=diagram(c);shape.dataset.chord=c;}if(typeof fitChordLabels==='function')fitChordLabels();}
async function hearChord(name){if(transport.state==='playing')pause();const gen=++transport.generation;try{await initAudio();if(gen!==transport.generation)return;silence();makeGate();strum(name,ctx.currentTime+.025,.9);}catch{toast('Tap Hear chord again to enable audio.');}}
function awardStar(){challengeStars=Math.min(3,challengeStars+1);const p=document.querySelector('.shell-progress');if(p){p.setAttribute('aria-label',`Class progress: ${challengeStars} of 3 stars`);p.querySelectorAll('span').forEach((el,i)=>el.classList.toggle('earned',i<challengeStars));}$('teamMessage').textContent=challengeStars===3?'Three class stars! You’re a chord-changing team.':'Class star '+challengeStars+'! Keep listening to each other.';broadcastProjection();}
function nextChallengeLevel(){const current=+$('challengeBeats').value;if(current===2){toast('You’re at two beats! Try the change in your song.');return;}$('challengeBeats').value=String(current===8?4:2);challengeStars=0;document.querySelectorAll('.shell-progress span').forEach(x=>x.classList.remove('earned'));$('teamMessage').textContent='New round · same steady tempo, fewer beats.';buildChallenge(false);}
function openBand(){showClass('band','Your backing band','PLAY TOGETHER');const b=song.band||DEFAULT_BAND,p=bandProfile(song);$('classContent').innerHTML=`<div class="band-arrangement-card"><span class="eyebrow">${esc(song.title)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><label for="bandStyle">Accompaniment<select id="bandStyle">${Object.entries(BAND_STYLES).map(([key,name])=>`<option value="${key}" ${b.style===key?'selected':''}>${name}</option>`).join('')}</select></label></div><label class="check" style="margin-bottom:18px"><input id="bandEnabled" type="checkbox" ${b.enabled?'checked':''}>Backing band on</label><div class="mixer">${[['ukulele','Ukulele','Four strings · high-G tuning'],['bass','Acoustic bass','A warm foundation for each chord'],['drums','Percussion','Kick, side stick, brushes, and hand claps'],['shaker','Shaker','A quiet pulse between the beats'],['melody','Mallets & bells','Chord-tone accompaniment · students sing the melody']].map(([key,name,note])=>`<div class="mix-channel"><label for="mix-${key}">${name}<output id="mixValue-${key}">${b[key]}%</output></label><input id="mix-${key}" data-mix="${key}" type="range" min="0" max="100" value="${b[key]}"><small>${note}</small></div>`).join('')}</div><div class="row" style="margin-top:20px"><button data-band-play class="primary">${transport.state==='playing'?'Ⅱ Pause':'▶ Listen to our band'}</button><button data-band-stop>■ Stop</button><button data-band-preset="song">Song mix</button><button data-band-preset="gentle">Gentle</button><button data-band-preset="full">Full band</button></div><p class="mixer-note">The band follows your chords and tempo. Turning it off leaves ukulele only. Your count-in stays audible even with the instruments turned down.</p><p id="soundStatus" class="hint" role="status">${soundStatusText()}</p><button id="retrySounds" data-retry-sounds ${soundState==='fallback'?'':'hidden'}>Retry sampled sounds</button><p class="sound-credit">Sounds from GeneralUser GS 1.471 by S. Christian Collins. <a href="https://www.schristiancollins.com/" target="_blank" rel="noopener">SoundFont creator ↗</a></p>`;}
function setMix(key,value){song.band=song.band||{...DEFAULT_BAND};song.band[key]=Math.round(clamp(value,0,100,0));if(key==='ukulele'){$('volume').value=song.band[key];if(ukeBus&&ctx)ukeBus.gain.setTargetAtTime(song.band[key]/100,ctx.currentTime,.025);}syncBandMix();if($('mixValue-'+key))$('mixValue-'+key).textContent=song.band[key]+'%';changed();}
function openSections(){showClass('sections','Arrange your song','Verse, chorus, and room to repeat');renderSectionsDialog();}
function renderSectionsDialog(){const list=sections();$('classContent').innerHTML=`<p class="lesson-note">Start a section at the selected measure, then duplicate or move the whole section with its chords and lyrics.</p><div class="row"><label>Start at measure<input id="sectionStart" type="number" min="1" max="${song.measures.length}" value="${selected+1}"></label><label>Section name<input id="sectionName" maxlength="45" placeholder="e.g. Verse 1 or Chorus"></label><button data-section-add class="primary">Add section</button></div><div class="section-list">${list.map((s,i)=>`<div class="section-row"><div><strong>${esc(s.name)}</strong><small>Measures ${s.start+1}–${s.end}</small></div><button data-section-action="rename" data-index="${i}">Rename</button><button data-section-action="duplicate" data-index="${i}">Duplicate</button><button data-section-action="up" data-index="${i}" ${i===0?'disabled':''} aria-label="Move ${esc(s.name)} earlier">↑</button><button data-section-action="down" data-index="${i}" ${i===list.length-1?'disabled':''} aria-label="Move ${esc(s.name)} later">↓</button><button data-section-action="practice" data-index="${i}">Practice</button>${i?`<button data-section-action="join" data-index="${i}">Join previous</button>`:''}</div>`).join('')}</div><p class="hint">“Join previous” removes a section label. All measures stay in the song. Undo edit can restore arrangement changes.</p>`;}
function sectionAction(action,index){const list=sections(),s=list[index];if(!s)return;if(action==='practice'){$('classModal').close();classTool='';practiceRange(s.start,s.end,true);return;}if(action==='rename'){const name=prompt('Section name:',s.name);if(name?.trim())mutate(()=>song.measures[s.start].sectionStart=name.trim().slice(0,45));}else if(action==='join'){mutate(()=>song.measures[s.start].sectionStart='');}else if(action==='duplicate'){if(song.measures.length+s.end-s.start>1024){toast('A song can have up to 1,024 measures.');return;}mutate(()=>{if(!song.measures[s.start].sectionStart)song.measures[s.start].sectionStart=s.name;const bars=clone(song.measures.slice(s.start,s.end));bars[0].sectionStart=s.name+' copy';song.measures.splice(s.end,0,...bars);activeRange=null;});}else if(action==='up'||action==='down'){const other=index+(action==='up'?-1:1);if(other<0||other>=list.length)return;mutate(()=>{const blocks=list.map(v=>{const bars=clone(song.measures.slice(v.start,v.end));bars[0].sectionStart=v.name;return bars;});[blocks[index],blocks[other]]=[blocks[other],blocks[index]];song.measures=blocks.flat();activeRange=null;selected=0;});}renderSectionsDialog();}
function practiceRange(startBar,endBar,repeat){stop(false);activeRange={start:Math.floor(clamp(startBar,0,song.measures.length-1)),end:Math.floor(clamp(endBar,1,song.measures.length)),loop:repeat};if(activeRange.end<=activeRange.start)activeRange.end=activeRange.start+1;$('rangeStart').value=activeRange.start+1;$('rangeEnd').value=activeRange.end;$('rangeLoop').checked=repeat;renderAll();start();}
let setlists=[],activeSetlistId='',setlistPosition=-1;
function loadSetlists(){const raw=readStore('uke-strum-setlists-v1',[]);if(Array.isArray(raw))for(const item of raw.slice(0,40)){try{if(!Array.isArray(item.songs))continue;setlists.push({id:String(item.id||uid()),name:String(item.name||'Class setlist').slice(0,80),songs:item.songs.slice(0,100).map(normalizeSong)});}catch{}}activeSetlistId=setlists[0]?.id||'';}
function currentSetlist(){return setlists.find(s=>s.id===activeSetlistId);}
function persistSetlists(){return writeStore('uke-strum-setlists-v1',setlists);}
function openSetlists(){showClass('setlists','Class setlists','A whole lesson, ready to go');renderSetlists();}
function renderSetlists(){const list=currentSetlist();const choices=[...STARTERS,...savedSongs];$('classContent').innerHTML=`<p class="lesson-note">Keep a song sequence for each class. Each entry keeps a snapshot of its arrangement, tempo, stage, and band.</p><div class="row"><label>Setlist<select id="setlistSelect">${setlists.map(s=>`<option value="${esc(s.id)}" ${s.id===activeSetlistId?'selected':''}>${esc(s.name)}</option>`).join('')||'<option>No setlists yet</option>'}</select></label><button data-setlist-new class="primary">＋ New setlist</button>${list?'<button data-setlist-rename>Rename</button><button data-setlist-delete>Delete setlist</button>':''}</div>${list?`<div class="row" style="margin-top:18px"><button data-setlist-add-current class="new-song-cta">＋ Add current song</button><label>Or choose a song<select id="setlistSongChoice">${choices.map((s,i)=>`<option value="${i}">${esc(s.title)}${i<STARTERS.length?' · starter':' · saved'}</option>`).join('')}</select></label><button data-setlist-add-choice>Add</button></div><div class="setlist-songs">${list.songs.map((s,i)=>`<div class="setlist-song"><div><strong>${i+1}. ${esc(s.title)}</strong><small>${s.meter} · ${s.tempo} BPM · ${esc(THEMES[s.theme]||THEMES.sunny)}</small></div><button data-setlist-load="${i}" class="primary">Load song</button><button data-setlist-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${esc(s.title)} earlier">↑</button><button data-setlist-move="${i}" data-direction="1" ${i===list.songs.length-1?'disabled':''} aria-label="Move ${esc(s.title)} later">↓</button><button data-setlist-remove="${i}">Remove</button></div>`).join('')||'<div class="empty-card">Start with a warm-up, add a familiar song, then finish with a class favorite.</div>'}</div><div class="row"><button data-setlist-export>Export this setlist</button><button data-setlist-next ${!list.songs.length?'disabled':''}>Load next song →</button></div>`:'<div class="empty-card" style="margin-top:18px">Create your first setlist: try “Grade 2 · First ukulele lesson.”</div>'}<div class="row" style="margin-top:16px"><button data-setlist-import>Import setlist</button><input id="setlistImportFile" type="file" accept=".json,application/json" hidden></div><p class="hint" style="margin-top:12px">Setlists stay in this browser. Export to back up or share. Editing a loaded song does not change the stored setlist snapshot; remove and add it again to update.</p>`;}
function addToSetlist(raw){const s=currentSetlist();if(!s)return;if(s.songs.length>=100){toast('A setlist can hold up to 100 songs.');return;}s.songs.push(normalizeSong(clone(raw)));persistSetlists();renderSetlists();}
function loadSetlistSong(i){const s=currentSetlist();if(!s||!s.songs[i])return;if(loadSong(s.songs[i])){setlistPosition=i;$('classModal').close();classTool='';toast(`Setlist: ${i+1} of ${s.songs.length} · ${s.songs[i].title}`);}}
async function importSetlist(file){try{if(file.size>5*1024*1024)throw Error('Choose a setlist under 5 MB.');const raw=JSON.parse(await file.text());if(raw.format!=='uke-strum-setlist'||!Array.isArray(raw.songs)||raw.songs.length>100)throw Error('Choose an exported Uke Strum setlist.');if(setlists.length>=40)throw Error('This browser already has 40 setlists.');const list={id:uid(),name:String(raw.name||'Imported setlist').slice(0,80),songs:raw.songs.map(normalizeSong)};setlists.push(list);activeSetlistId=list.id;setlistPosition=-1;persistSetlists();renderSetlists();toast('Setlist imported.');}catch(e){toast('Could not import: '+e.message);}}
function projectorIsOpen(){return !!projectorWindow&&!projectorWindow.closed;}
function openProjector(){if(!('BroadcastChannel' in window)){toast('This browser does not support a separate student display. Use Classroom view.');return;}if(projectorIsOpen()){projectorWindow.focus();return;}projectorId=uid();const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('projector',projectorId);projectorWindow=window.open(url.href,'uke-projector-'+projectorId,'popup,width=1280,height=800');if(!projectorWindow){toast('Allow this site’s pop-up window, then click Open student display again.');return;}projectorChannel?.close();projectorChannel=new BroadcastChannel('uke-projector-'+projectorId);projectorChannel.onmessage=e=>{if(e.data?.type==='ready')broadcastProjection(true);};$('projectorStatus').textContent='Student display open · press Play in this teacher window';toast('Student display opened. Press Play in this teacher window.');broadcastProjection(true);}
let projectionSong='',projectionAnchor=null,projectionRAF=0;
function broadcastProjection(force=false){if(isProjector||!projectorChannel||!projectorIsOpen())return;const serialized=JSON.stringify(song),include=force||serialized!==projectionSong;projectionSong=serialized;const playing=transport.state==='playing',phase=playing&&ctx?(ctx.currentTime-transport.origin)/duration():transport.pos/duration();const counting=(playing||transport.state==='paused')&&phase<(transport.countUntil||0);const packet={type:'state',song:include?clone(song):null,state:transport.state,tick:transport.tick,phase,until:transport.countUntil||0,range:activeRange,count:counting?Math.floor(phase)-(transport.countUntil||0):null,stars:challengeStars,exercise:classTool==='challenge'||(classTool==='lesson'&&lessonStep===1),finished:transport.state==='finished'};projectorChannel.postMessage(packet);}
function renderProjectorWaiting(connected=false){
 activeCue=null;$('stage').classList.remove('counting');$('lyricStage').hidden=false;$('lyricProgress').hidden=true;
 renderLyricLines('Press Play in your teacher window',connected?cueAt(transport.tick)?.text||'Keep the teacher window open for controls and sound.':'Keep the teacher window open for controls and sound.','projector-waiting',false);
 $('endingCue').textContent='Controls and sound stay in the teacher window.';
}
function initProjector(){document.body.classList.add('projector-only');$('editor').hidden=true;$('stage').hidden=false;document.title='Uke Strum · Student display';$('stageTitle').textContent='Student display';renderProjectorWaiting();document.body.insertAdjacentHTML('beforeend','<button id="projectorFullscreen">Full screen</button><div id="projectorNotice" class="projector-notice" role="status" hidden></div>');$('projectorFullscreen').onclick=()=>$('fullscreenBtn').click();if(!('BroadcastChannel' in window)){$('currentLyric').textContent='Use Classroom view in the main window';return;}projectorChannel=new BroadcastChannel('uke-projector-'+query.get('projector'));projectorChannel.onmessage=e=>{const p=e.data;if(!p||p.type!=='state')return;try{const priorState=transport.state;if(p.song){song=normalizeSong(p.song);renderAll();}activeRange=p.range;transport.state=p.state;transport.countUntil=p.until;transport.tick=p.tick;projectionAnchor={phase:p.phase,at:performance.now(),playing:p.state==='playing',counting:p.count!==null};lastProjectorTick=Date.now();$('projectorNotice').hidden=true;if(p.count!==null){renderCount(p.count);renderLyricsAt(p.phase,true);}else if(!p.finished||priorState!=='finished'){const tick=p.state==='playing'?Math.floor(swingPhase(mappedTick(p.phase))):p.tick;renderPosition(tick,p.phase);}if(p.finished){renderLyricLines('','','finished',false);$('endingCue').textContent='';$('nextChord').textContent='✓';}if(p.exercise&&p.count===null)$('nextLyric').textContent=`Class stars: ${'★'.repeat(p.stars)}${'☆'.repeat(3-p.stars)} · Listen and change together`;updateTransport();if(p.state==='stopped')renderProjectorWaiting(true);else if(p.state==='paused')$('endingCue').textContent='Paused · resume in your teacher window.';}catch{renderProjectorWaiting();}};projectorChannel.postMessage({type:'ready'});function animateProjection(){if(projectionAnchor?.playing){const phase=projectionAnchor.phase+(performance.now()-projectionAnchor.at)/1000/duration(),w=playbackPlan();if(w.loop||phase<w.finish)renderLyricsAt(phase,phase<transport.countUntil);}projectionRAF=requestAnimationFrame(animateProjection);}animateProjection();setInterval(()=>{if(lastProjectorTick&&Date.now()-lastProjectorTick>5000){$('projectorNotice').hidden=false;$('projectorNotice').textContent='Teacher window disconnected · reopen the student display from Uke Strum';};},2000);}
function encodeShared(raw){const clean=normalizeSong(raw);clean.id=null;const bytes=new TextEncoder().encode(JSON.stringify(clean));let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function decodeShared(value){if(value.length>1500000)throw Error('This song link is too large. Import its song file instead.');const str=atob(value.replace(/-/g,'+').replace(/_/g,'/'));return normalizeSong(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(str,c=>c.charCodeAt(0)))));}
function openShare(){showClass('share','Share a little music','Ready for another music room');$('classContent').innerHTML=`<p class="lesson-note">Share “${esc(song.title)}” with its chords, lyrics, strum, stage, and band settings.</p><div class="share-options"><div class="share-option"><h3>Song preview link</h3><p>Opens a play-along preview with a <b>Make my own copy</b> button. Recipients need access to this site; its sharing permissions stay the same.</p><button data-share-link class="primary">Create preview link</button></div><div class="share-option"><h3>Portable song player</h3><p>One HTML file with the song and classroom tools inside. Another teacher can open it in a browser, play along, and make an editable copy. No site access required.</p><button data-share-player class="new-song-cta">Download song player</button></div></div><label id="shareLinkLabel" hidden>Preview link<input id="shareLinkOutput" class="share-link" readonly></label><p id="shareMessage" role="status" class="hint"></p><div class="row" style="margin-top:18px"><button data-share-json>Export editable song JSON</button><button data-share-preview>Preview this song</button></div><p class="hint" style="margin-top:14px">Share songs and lyrics you have permission to distribute. Setlists have their own export in Class setlists.</p>`;}
async function createShareLink(){if(location.protocol==='file:'){toast('Use the portable player file or export JSON to share from this downloaded copy.');return;}const url=new URL(location.href);url.search='';url.hash='song='+encodeShared(song);if(url.href.length>16000){$('shareMessage').textContent='This arrangement is too large for a convenient link. Download the portable song player or export JSON.';return;}$('shareLinkLabel').hidden=false;$('shareLinkOutput').value=url.href;try{await navigator.clipboard.writeText(url.href);$('shareMessage').textContent='Link copied. It works for people who have access to this site.';}catch{$('shareLinkOutput').focus();$('shareLinkOutput').select();$('shareMessage').textContent='Copy the selected link to share it.';}}
async function downloadPlayer(){
 const button=document.querySelector('[data-share-player]');
 if(window.PORTABLE_SONG&&location.protocol==='file:'){toast('Share this HTML file itself, or export an updated song JSON.');return;}
 if(button)button.disabled=true;$('shareMessage').textContent='Preparing your player, illustrations, and instruments…';
 try{
  const base=new URL('.',location.href),names=['index.html','classroom.css','beach.css','app.js','arrangements.js','classroom.js','soundfont.js','strum-hand.js','beach.js','boot.js'];
  const responses=await Promise.all(names.map(name=>fetch(new URL(name,base))));
  if(responses.some(r=>!r.ok))throw Error('Could not read the player files.');
  const contents=await Promise.all(responses.map(r=>r.text()));
  const soundbank=await readSoundBank();
  const artwork=Object.fromEntries(await Promise.all(COLLAGE_ART_ASSETS.map(async path=>{
   const response=await fetch(new URL(path,base));if(!response.ok)throw Error('Could not read an illustration.');
   const bytes=new Uint8Array(await response.arrayBuffer());let binary='';
   for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));
   return [path,'data:'+(path.endsWith('.png')?'image/png':'image/webp')+';base64,'+btoa(binary)];
  })));
  let output=contents[0].replace(/<script src="(?:pro-help|video-island|harmony-model|harmony-sync|video-fast|score-playback-model|score-playback-renderer|score-playback|melody-model|melody-renderer|melody-pdf|melody-studio|vendor\/vexflow|video-model|video-renderer|video-studio|practice-sheet|practice-pdf|vendor\/pdf-lib.min|vendor\/fontkit.umd.min)\.js"><\/script>/g,'').replace('<link rel="stylesheet" href="video-studio.css">','').replace('<link rel="stylesheet" href="melody-studio.css">','').replace('<link rel="stylesheet" href="score-playback.css">','');
  for(let i=1;i<names.length;i++){
   const name=names[i];
   if(name.endsWith('.css'))output=output.replace(`<link rel="stylesheet" href="${name}">`,()=>'<style>'+contents[i]+'</style>');
   else output=output.replace(`<script src="${name}"></script>`,()=>'<script>'+contents[i].replace(/<\/script/gi,'<\\/script')+'</script>');
  }
  const safeJSON=value=>JSON.stringify(value).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
  output=output.replace('<script>',()=>'<script>window.EMBEDDED_ART='+safeJSON(artwork)+';window.EMBEDDED_SOUNDBANK='+safeJSON(soundbank)+';window.PORTABLE_SONG='+safeJSON(normalizeSong(song))+';</script>\n<script>');
  downloadFile(output,song.title+'_Play_Along.html','text/html');$('shareMessage').textContent='Player downloaded with all illustrations and instruments. Send the HTML file; open it in a browser and press Play.';
 }catch(e){$('shareMessage').textContent='Could not prepare the player. Export song JSON is available as a backup.';}
 finally{if(button)button.disabled=false;}
}

function downloadFile(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name.replace(/[^a-zA-Z0-9_.-]+/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
let previewBackup=null;
function previewSong(raw){leaveExercise();stop(false);if(!previewBackup)previewBackup={song:clone(song),dirty,selected,undo:clone(undoStack)};isViewer=true;activeRange=null;song=normalizeSong(raw);song.id=null;renderAll();$('classModal').close();classTool='';$('editor').inert=true;$('stage').hidden=false;$('sharePreview').hidden=false;$('sharePreviewName').textContent=song.title;document.body.classList.add('preview-mode');document.body.style.overflow='hidden';$('previewPlay').focus();}
function closePreview(copy=false){stop(false);const copied=clone(song);isViewer=false;$('sharePreview').hidden=true;document.body.classList.remove('preview-mode');$('stage').hidden=true;$('editor').inert=false;document.body.style.overflow='';if(location.hash.startsWith('#song='))history.replaceState(null,'',location.pathname+location.search);if(copy){copied.id=null;copied.title=(copied.title+' · my copy').slice(0,120);song=copied;selected=0;undoStack=[];dirty=true;changed();toast('Your editable copy is ready. Save song to keep it in My songs.');}else if(previewBackup){song=previewBackup.song;dirty=previewBackup.dirty;selected=previewBackup.selected;undoStack=previewBackup.undo;if(dirty)changed();}previewBackup=null;renderAll();$('songTitle').focus();}
function initClassroom(){
 song=normalizeSong(song);loadSetlists();
 $('teachBtn').onclick=()=>openLesson(0);$('challengeBtn').onclick=openChallenge;$('bandBtn').onclick=openBand;$('stageBand').onclick=openBand;$('setlistBtn').onclick=openSetlists;$('sectionsBtn').onclick=openSections;$('shareBtn').onclick=openShare;$('projectorBtn').onclick=openProjector;
 $('classClose').onclick=closeClass;$('classModal').addEventListener('cancel',e=>{e.preventDefault();closeClass();});
 $('stageTheme').onchange=e=>{song.theme=e.target.value;changed();applyTheme();broadcastProjection(true);};
 $('volume').oninput=e=>setMix('ukulele',e.target.value);
 $('rangePlay').onclick=()=>practiceRange(+$('rangeStart').value-1,+$('rangeEnd').value,$('rangeLoop').checked);
 $('rangeClear').onclick=()=>{stop(false);activeRange=null;stop();renderAll();};
 $('sectionChips').onclick=e=>{const b=e.target.closest('[data-section]');if(!b)return;const s=sections()[+b.dataset.section];selected=s.start;$('rangeStart').value=s.start+1;$('rangeEnd').value=s.end;renderMeasures();renderInspector();$('measuresGrid').children[selected]?.scrollIntoView({block:'nearest',behavior:'smooth'});};
 $('classContent').onclick=async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;try{
  if(d.lesson!==undefined){if(lessonStep===3&&+d.lesson===3){performLesson();}else{lessonStep=+d.lesson;renderLesson();}}
  else if(d.repeat!==undefined){if(lessonStep===1)challengeStars=0;renderLesson();}
  else if(d.hear!==undefined){await hearChord(d.hear);}
  else if(d.lessonPerform!==undefined){performLesson();}
  else if(d.lessonBand!==undefined){openBand();$('classContent').insertAdjacentHTML('beforeend','<button data-back-lesson style="margin-top:12px">← Back to the lesson</button>');}
  else if(d.backLesson!==undefined){openLesson(3);}
  else if(b.id==='exercisePlay'){await start();}
  else if(d.exerciseStop!==undefined){stop();}
  else if(d.earned!==undefined){awardStar();}
  else if(d.nextLevel!==undefined){nextChallengeLevel();}
  else if(d.bandPlay!==undefined){await start();b.textContent=transport.state==='playing'?'Ⅱ Pause':'▶ Listen to our band';}
  else if(d.bandStop!==undefined){stop();const play=document.querySelector('[data-band-play]');if(play)play.textContent='▶ Listen to our band';}
  else if(d.bandPreset!==undefined){song.band=d.bandPreset==='song'?{...bandDefaults(song),enabled:true}:{...song.band,enabled:true,...(d.bandPreset==='gentle'?{bass:27,drums:12,shaker:9,melody:10}:{bass:42,drums:30,shaker:22,melody:23})};setMix('ukulele',song.band.ukulele);syncBandMix();changed();openBand();}
  else if(d.retrySounds!==undefined){await basicInitAudio();await loadSampledSounds();}
  else if(d.sectionAdd!==undefined){const name=$('sectionName').value.trim();if(!name){$('sectionName').focus();return;}const i=Math.floor(clamp(+$('sectionStart').value-1,0,song.measures.length-1));mutate(()=>song.measures[i].sectionStart=name.slice(0,45));renderSectionsDialog();}
  else if(d.sectionAction!==undefined){sectionAction(d.sectionAction,+d.index);}
  else if(d.setlistNew!==undefined){if(setlists.length>=40){toast('This browser can hold 40 setlists. Export one before removing it.');return;}const name=prompt('Name your class setlist:','My ukulele class');if(name?.trim()){const list={id:uid(),name:name.trim().slice(0,80),songs:[]};setlists.push(list);activeSetlistId=list.id;setlistPosition=-1;persistSetlists();renderSetlists();}}
  else if(d.setlistRename!==undefined){const list=currentSetlist(),name=prompt('Setlist name:',list.name);if(name?.trim()){list.name=name.trim().slice(0,80);persistSetlists();renderSetlists();}}
  else if(d.setlistDelete!==undefined){if(confirm('Delete this setlist from this browser? Saved songs stay in My songs.')){setlists=setlists.filter(s=>s.id!==activeSetlistId);activeSetlistId=setlists[0]?.id||'';setlistPosition=-1;persistSetlists();renderSetlists();}}
  else if(d.setlistAddCurrent!==undefined){addToSetlist(song);}
  else if(d.setlistAddChoice!==undefined){addToSetlist([...STARTERS,...savedSongs][+$('setlistSongChoice').value]);}
  else if(d.setlistLoad!==undefined){loadSetlistSong(+d.setlistLoad);}
  else if(d.setlistNext!==undefined){const list=currentSetlist();if(setlistPosition+1<list.songs.length)loadSetlistSong(setlistPosition+1);else toast('You reached the end of this setlist.');}
  else if(d.setlistMove!==undefined){const list=currentSetlist(),i=+d.setlistMove,j=i+(+d.direction);if(j>=0&&j<list.songs.length){[list.songs[i],list.songs[j]]=[list.songs[j],list.songs[i]];setlistPosition=-1;persistSetlists();renderSetlists();}}
  else if(d.setlistRemove!==undefined){currentSetlist().songs.splice(+d.setlistRemove,1);setlistPosition=-1;persistSetlists();renderSetlists();}
  else if(d.setlistExport!==undefined){const list=currentSetlist();downloadJSON({format:'uke-strum-setlist',version:1,name:list.name,songs:list.songs},list.name);}
  else if(d.setlistImport!==undefined){$('setlistImportFile').click();}
  else if(d.shareLink!==undefined){await createShareLink();}
  else if(d.sharePlayer!==undefined){await downloadPlayer();}
  else if(d.shareJson!==undefined){downloadJSON({format:'uke-strum',version:3,song},song.title);}
  else if(d.sharePreview!==undefined){previewSong(clone(song));}
 }catch(err){toast(err.message||'Please try that again.');}};
 $('classContent').oninput=e=>{const key=e.target.dataset.mix;if(key)setMix(key,e.target.value);};
 $('classContent').onchange=e=>{const el=e.target;if(['challengeA','challengeB','challengeBeats','challengeTempo'].includes(el.id)){buildChallenge(false);}else if(el.id==='strumPracticeTempo'){stop(false);song.tempo=Math.round(clamp(el.value,40,200,60));el.value=song.tempo;renderAll();}else if(el.id==='bandEnabled'){song.band.enabled=el.checked;syncBandMix();changed();}else if(el.id==='bandStyle'){song.band.style=Object.hasOwn(BAND_STYLES,el.value)?el.value:'song';changed();openBand();}else if(el.id==='setlistSelect'){activeSetlistId=el.value;setlistPosition=-1;renderSetlists();}else if(el.id==='setlistImportFile'&&el.files[0]){importSetlist(el.files[0]);}};
 $('previewPlay').onclick=async()=>{await start();$('previewPlay').textContent=transport.state==='playing'?'Ⅱ Pause':'▶ Play along';};$('previewCopy').onclick=()=>closePreview(true);$('previewClose').onclick=()=>closePreview(false);
 $('returnLesson').onclick=()=>{$('lessonDock').hidden=true;exitStage();openLesson(3);};
 const oldExit=exitStage;exitStage=function(){if(isProjector)return;if(isViewer){closePreview(false);return;}oldExit();};$('exitStage').onclick=()=>exitStage();
 document.querySelector('.stage-controls .row').insertAdjacentHTML('beforeend','<button id="stageNextSetlist" hidden>Next setlist song →</button>');$('stageNextSetlist').onclick=()=>{const list=currentSetlist();if(list&&setlistPosition+1<list.songs.length){loadSetlistSong(setlistPosition+1);$('performBtn').click();}};
 const update=updateTransport;updateTransport=function(){update();const list=currentSetlist(),b=$('stageNextSetlist');if(b){b.hidden=isViewer||!list||setlistPosition<0;b.disabled=!list||setlistPosition+1>=list.songs.length;}};
 const baseHelp=$('helpBtn').onclick;$('helpBtn').onclick=()=>{baseHelp();$('generalContent').insertAdjacentHTML('beforeend','<h3 style="margin-top:20px">Your classroom toolkit</h3><p class="modal-note"><b>Teach this song</b> guides the class through chords, changes, strum, and performance. <b>Chord challenge</b> gives teacher-awarded class stars. <b>Build your band</b> adds sampled bass, percussion, shaker, and mallets with a song arrangement. Use <b>Arrange sections</b> to label, copy, or reorder verses and choruses. <b>Practice a passage</b> repeats selected measures with the count-in. <b>Class setlists</b> save lesson sequences. Choose one of three stages, then <b>Open student display</b> for a separate screen. Press Play in your original teacher window; playback controls and sound stay there. <b>Share song</b> creates previews, editable JSON, or a portable HTML player.</p>');};
 renderAll();if(isProjector){initProjector();return;}
 if(window.PORTABLE_SONG){try{previewSong(window.PORTABLE_SONG);}catch{isViewer=false;toast('This portable song could not be loaded.');}}
 else if(location.hash.startsWith('#song=')){try{previewSong(decodeShared(location.hash.slice(6)));}catch(e){isViewer=false;toast('Could not open this song link: '+e.message);}}
 setInterval(()=>{if(projectorIsOpen()){if(document.hidden&&transport.state==='playing'){cancelAnimationFrame(transport.frame);draw();}broadcastProjection();}else if(projectorWindow){$('projectorStatus').textContent='Student display closed';projectorWindow=null;projectorChannel?.close();projectorChannel=null;projectionSong='';}},250);
}
function performLesson(){leaveExercise();$('classModal').close();$('lessonDock').hidden=false;$('lessonDockText').textContent='Lesson 4 of 4 · Let’s play the whole song';$('performBtn').click();}
